import { useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { ChatBubbleLeftIcon, TrashIcon } from '@heroicons/react/24/outline'
import {
  CheckCircleIcon,
  ClipboardDocumentListIcon,
  EyeIcon,
  MagnifyingGlassIcon,
  MegaphoneIcon,
  WrenchScrewdriverIcon,
} from '@heroicons/react/24/solid'
import { Button } from '@astryxdesign/core/Button'
import { Card } from '@astryxdesign/core/Card'
import { Dialog, DialogHeader } from '@astryxdesign/core/Dialog'
import { Layout, LayoutContent } from '@astryxdesign/core/Layout'
import { Link } from '@astryxdesign/core/Link'
import { HStack, VStack } from '@astryxdesign/core/Stack'
import { Heading, Text } from '@astryxdesign/core/Text'
import { api, type TicketOut } from '../lib/api'
import { describeLatestAction } from '../lib/eventDisplay'
import { formatRelative } from '../lib/time'

// Priority order for "smart" display -- whatever most needs an operator's
// attention floats to the top; a fully closed ticket needs nothing further
// from anyone, so it sinks to the very end regardless of how recent it is.
const STATE_ORDER = ['escalated', 'in_review', 'resolving', 'planned', 'investigating', 'completed'] as const

const STATE_LABEL: Record<string, string> = {
  investigating: 'Investigating',
  planned: 'Planned',
  resolving: 'Resolving',
  in_review: 'In Review',
  completed: 'Completed',
  escalated: 'Escalated',
}

const STATE_ICON: Record<string, typeof CheckCircleIcon> = {
  investigating: MagnifyingGlassIcon,
  planned: ClipboardDocumentListIcon,
  resolving: WrenchScrewdriverIcon,
  in_review: EyeIcon,
  completed: CheckCircleIcon,
  escalated: MegaphoneIcon,
}

// Six genuinely distinct, saturated colors -- not just red/green, and not
// two states sharing one color (resolving and in_review used to both land
// on "orange"). Each is only ever used for a small icon, never as a full
// card/strip background tint (that read as "ugly" -- a card's real content
// should stay neutral, with color reserved for the one glanceable accent).
const STATE_COLOR: Record<string, { fg: string; bg: string }> = {
  investigating: { fg: 'var(--color-icon-cyan)', bg: 'var(--color-background-cyan)' },
  planned: { fg: 'var(--color-icon-purple)', bg: 'var(--color-background-purple)' },
  resolving: { fg: 'var(--color-icon-yellow)', bg: 'var(--color-background-yellow)' },
  in_review: { fg: 'var(--color-icon-pink)', bg: 'var(--color-background-pink)' },
  completed: { fg: 'var(--color-icon-green)', bg: 'var(--color-background-green)' },
  escalated: { fg: 'var(--color-icon-red)', bg: 'var(--color-background-red)' },
}

// The elegant, non-button filter row: a single-select set of labels, each
// carrying its own count, "All" first and active by default. Not styled as
// buttons on purpose -- clicking one narrows the list to just that state;
// there's no multi-select, since seeing several states at once alongside
// "all of them" is the exact redundant utility this was asked to drop.
function FilterTabs({
  counts,
  active,
  onSelect,
}: {
  counts: Record<string, number>
  active: string | null
  onSelect: (state: string | null) => void
}) {
  const total = Object.values(counts).reduce((sum, n) => sum + n, 0)
  return (
    <HStack gap={4} wrap="wrap" align="center">
      <FilterTab label="All" count={total} isActive={active === null} onClick={() => onSelect(null)} />
      {STATE_ORDER.map((state) => (
        <FilterTab
          key={state}
          label={STATE_LABEL[state]}
          count={counts[state] ?? 0}
          isActive={active === state}
          onClick={() => onSelect(state)}
        />
      ))}
    </HStack>
  )
}

function FilterTab({
  label,
  count,
  isActive,
  onClick,
}: {
  label: string
  count: number
  isActive: boolean
  onClick: () => void
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        border: 'none',
        background: 'none',
        padding: '2px 0',
        cursor: 'pointer',
        display: 'flex',
        alignItems: 'baseline',
        gap: 5,
        borderBottom: isActive ? '2px solid var(--color-text-primary)' : '2px solid transparent',
      }}
    >
      <Text
        type="body"
        weight={isActive ? 'bold' : 'normal'}
        style={{ color: isActive ? 'var(--color-text-primary)' : 'var(--color-text-secondary)' }}
      >
        {label}
      </Text>
      <Text type="body" size="sm" color="secondary">
        {count}
      </Text>
    </button>
  )
}

function StateIcon({ state }: { state: string }) {
  const Icon = STATE_ICON[state] ?? ClipboardDocumentListIcon
  const { fg, bg } = STATE_COLOR[state] ?? STATE_COLOR.investigating
  return (
    <div
      style={{
        width: 32,
        height: 32,
        borderRadius: '50%',
        flexShrink: 0,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: bg,
      }}
    >
      <Icon style={{ width: 16, height: 16, color: fg }} />
    </div>
  )
}

function TicketCard({
  ticket,
  onOpen,
  onDelete,
}: {
  ticket: TicketOut
  onOpen: () => void
  onDelete: () => void
}) {
  const caption = ticket.latest_event_name
    ? describeLatestAction(ticket.latest_event_name, ticket.latest_event_status ?? 'success')
    : 'No activity yet'

  return (
    <Card elevation="low" padding={4} onClick={onOpen} style={{ cursor: 'pointer' }}>
      <VStack gap={3}>
        <HStack align="center" gap={3}>
          <VStack gap={0} style={{ minWidth: 0, flex: 1 }}>
            <Text
              type="body"
              weight="bold"
              style={{
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
              }}
            >
              {ticket.title}
            </Text>
            <Text type="body" size="sm" color="secondary">
              {formatRelative(ticket.created_at)}
              {ticket.resource_id ? ` · ${ticket.resource_id}` : ''}
            </Text>
          </VStack>
          <Button
            label="Delete ticket"
            isIconOnly
            size="sm"
            variant="ghost"
            icon={<TrashIcon style={{ width: 14, height: 14 }} />}
            onClick={(event) => {
              event.stopPropagation()
              onDelete()
            }}
          />
        </HStack>

        <HStack
          align="center"
          style={{
            justifyContent: 'space-between',
            background: 'var(--color-background-muted)',
            borderRadius: 'var(--radius-container)',
            padding: '6px 10px',
          }}
        >
          <Text type="body" size="sm" weight="bold" color="secondary">
            {caption}
          </Text>
          <Text type="body" size="sm" color="secondary">
            {ticket.latest_event_ts ? formatRelative(ticket.latest_event_ts) : ''}
          </Text>
        </HStack>

        <HStack align="center" style={{ justifyContent: 'space-between' }}>
          <HStack gap={3} align="center">
            <HStack gap={1} align="center">
              <ChatBubbleLeftIcon style={{ width: 14, height: 14, color: 'var(--color-icon-secondary)' }} />
              <Text type="body" size="sm" color="secondary">
                {ticket.comment_count}
              </Text>
            </HStack>
            <Text type="body" size="sm" color="secondary">
              {ticket.event_count} events
            </Text>
          </HStack>
          <div onClick={(event) => event.stopPropagation()}>
            <Link href={`/logs?ticket=${ticket.id}`}>View logs</Link>
          </div>
        </HStack>
      </VStack>
    </Card>
  )
}

function DeleteTicketDialog({
  ticket,
  onCancel,
  onConfirm,
}: {
  ticket: TicketOut | null
  onCancel: () => void
  onConfirm: () => void
}) {
  return (
    <Dialog isOpen={ticket !== null} onOpenChange={(open) => !open && onCancel()} width={420} purpose="form">
      {ticket && (
        <Layout
          header={<DialogHeader title="Delete ticket?" onOpenChange={onCancel} />}
          content={
            <LayoutContent>
              <VStack gap={4}>
                <Text type="body">
                  Delete "{ticket.title}"? Its logged events will be kept, just unassigned from this ticket.
                </Text>
                <HStack gap={2} style={{ justifyContent: 'flex-end' }}>
                  <Button label="Cancel" variant="secondary" onClick={onCancel} />
                  <Button label="Delete" variant="destructive" onClick={onConfirm} />
                </HStack>
              </VStack>
            </LayoutContent>
          }
        />
      )}
    </Dialog>
  )
}

function sortByRecency(tickets: TicketOut[]): TicketOut[] {
  return tickets.slice().sort((a, b) => b.id - a.id)
}

// One state's section: a small header (icon + label + count) the cards
// themselves no longer repeat -- showing the same icon on every card in an
// already-grouped section said nothing a grid full of "Escalated" cards
// under an "Escalated" header didn't already say -- followed by a grid of
// that state's cards, several per row.
function StateSection({
  state,
  tickets,
  onOpen,
  onDelete,
}: {
  state: string
  tickets: TicketOut[]
  onOpen: (ticket: TicketOut) => void
  onDelete: (ticket: TicketOut) => void
}) {
  if (tickets.length === 0) return null
  return (
    <VStack gap={3}>
      <HStack align="center" gap={2}>
        <StateIcon state={state} />
        <Heading level={4}>{STATE_LABEL[state] ?? state}</Heading>
        <Text type="body" color="secondary">
          {tickets.length}
        </Text>
      </HStack>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 16 }}>
        {sortByRecency(tickets).map((ticket) => (
          <TicketCard
            key={ticket.id}
            ticket={ticket}
            onOpen={() => onOpen(ticket)}
            onDelete={() => onDelete(ticket)}
          />
        ))}
      </div>
    </VStack>
  )
}

// The Dashboard's ticket area: subsections in priority order (whatever most
// needs an operator's attention first), each a grid of that state's cards --
// not one flat list, and not side-by-side kanban columns either. The filter
// tab row narrows which subsection(s) show; "All" (default) shows every
// non-empty one, stacked top to bottom.
export function TicketsGrid({ tickets, onChanged }: { tickets: TicketOut[]; onChanged: () => void }) {
  const navigate = useNavigate()
  const [activeState, setActiveState] = useState<string | null>(null)
  const [pendingDelete, setPendingDelete] = useState<TicketOut | null>(null)

  const counts = useMemo(() => {
    const result: Record<string, number> = {}
    for (const ticket of tickets) result[ticket.state] = (result[ticket.state] ?? 0) + 1
    return result
  }, [tickets])

  const byState = useMemo(() => {
    const result: Record<string, TicketOut[]> = {}
    for (const ticket of tickets) (result[ticket.state] ??= []).push(ticket)
    return result
  }, [tickets])

  const visibleStates = activeState === null ? STATE_ORDER : [activeState]

  async function confirmDelete() {
    if (!pendingDelete) return
    await api.deleteTicket(pendingDelete.id)
    setPendingDelete(null)
    onChanged()
  }

  const hasAnyVisible = visibleStates.some((state) => (byState[state]?.length ?? 0) > 0)

  return (
    <VStack gap={5}>
      <FilterTabs counts={counts} active={activeState} onSelect={setActiveState} />
      {!hasAnyVisible ? (
        <Text type="body" color="secondary">
          {tickets.length === 0 ? 'No tickets yet.' : 'No tickets in this state.'}
        </Text>
      ) : (
        visibleStates.map((state) => (
          <StateSection
            key={state}
            state={state}
            tickets={byState[state] ?? []}
            onOpen={(ticket) => navigate(`/logs?ticket=${ticket.id}`)}
            onDelete={setPendingDelete}
          />
        ))
      )}
      <DeleteTicketDialog ticket={pendingDelete} onCancel={() => setPendingDelete(null)} onConfirm={confirmDelete} />
    </VStack>
  )
}

import { useEffect, useState } from 'react'
import { Button } from '@astryxdesign/core/Button'
import { Dialog, DialogHeader } from '@astryxdesign/core/Dialog'
import { Layout, LayoutContent } from '@astryxdesign/core/Layout'
import { HStack, VStack } from '@astryxdesign/core/Stack'
import { TextArea } from '@astryxdesign/core/TextArea'
import { Text } from '@astryxdesign/core/Text'
import { api, type CommentOut } from '../lib/api'
import { formatFullTime } from '../lib/time'

// A general-purpose annotation an operator can leave on any logged call --
// unrelated to a plan/report's own request-changes comment (that one lives
// in `error_message` and drives the approval flow; these are free-form
// notes with no effect on anything). One event's comment thread, shown as
// its own small popup rather than folded into the full detail dialog, so
// it's reachable directly from the timeline's own comment-count indicator.
export function CommentsDialog({
  eventId,
  eventLabel,
  onClose,
  onChanged,
}: {
  eventId: number | null
  eventLabel: string
  onClose: () => void
  onChanged: () => void
}) {
  const [comments, setComments] = useState<CommentOut[]>([])
  const [draft, setDraft] = useState('')
  const [isSending, setIsSending] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (eventId === null) return
    setError(null)
    api
      .listComments(eventId)
      .then(setComments)
      .catch((err: Error) => setError(err.message))
  }, [eventId])

  function submit() {
    const text = draft.trim()
    if (!text || eventId === null) return
    setIsSending(true)
    setError(null)
    api
      .addComment(eventId, text)
      .then((comment) => {
        setComments((current) => [...current, comment])
        setDraft('')
        onChanged()
      })
      .catch((err: Error) => setError(err.message))
      .finally(() => setIsSending(false))
  }

  return (
    <Dialog isOpen={eventId !== null} onOpenChange={(open) => !open && onClose()} width={480} purpose="form">
      {eventId !== null && (
        <Layout
          header={<DialogHeader title="Comments" subtitle={eventLabel} onOpenChange={onClose} />}
          content={
            <LayoutContent isScrollable>
              <VStack gap={4}>
                {comments.length === 0 ? (
                  <Text type="body" color="secondary">
                    No comments yet.
                  </Text>
                ) : (
                  <VStack gap={3}>
                    {comments.map((comment) => (
                      <VStack
                        gap={1}
                        key={comment.id}
                        style={{
                          background: 'var(--color-background-muted)',
                          borderRadius: 'var(--radius-container)',
                          padding: '8px 10px',
                        }}
                      >
                        <Text type="body" style={{ whiteSpace: 'pre-wrap' }}>
                          {comment.text}
                        </Text>
                        <Text type="body" size="xsm" color="secondary">
                          {formatFullTime(comment.created_at)}
                        </Text>
                      </VStack>
                    ))}
                  </VStack>
                )}

                {error && (
                  <Text type="body" style={{ color: 'var(--color-text-red)' }}>
                    {error}
                  </Text>
                )}

                <VStack gap={2}>
                  <TextArea
                    label="Add a comment"
                    isLabelHidden
                    placeholder="Add a comment..."
                    value={draft}
                    onChange={setDraft}
                    rows={3}
                  />
                  <HStack style={{ justifyContent: 'flex-end' }}>
                    <Button label="Comment" onClick={submit} isDisabled={!draft.trim() || isSending} />
                  </HStack>
                </VStack>
              </VStack>
            </LayoutContent>
          }
        />
      )}
    </Dialog>
  )
}

// Typed fetch helpers for the admin GUI backend (admin_gui/backend). Every
// call goes through the dev-time Vite proxy (vite.config.ts) or, in
// production, the same FastAPI process that serves this built frontend --
// so a bare `/api/...` path is always correct.

// `extends Record<string, unknown>` on every row-shaped type below is what
// `@astryxdesign/core/Table`'s `data` prop requires (its own docs: "T must
// extend Record<string, unknown>") -- not just a TypeScript nicety.

export interface ServerSummary extends Record<string, unknown> {
  id: string
  description: string
}

export interface ToolSummary extends Record<string, unknown> {
  name: string
  description: string
  read_only: boolean | null
  destructive: boolean | null
}

export interface OperationSummary extends Record<string, unknown> {
  operation_id: string
  summary: string
  category: string | null
  risk_level: string | null
  read_only: boolean
  destructive: boolean
  pinned: boolean
}

export interface OperationParameter extends Record<string, unknown> {
  name: string
  location: string
  required: boolean
  schema: Record<string, unknown>
}

export interface OperationDetail extends Record<string, unknown> {
  operation_id: string
  method: string
  path: string
  summary: string
  description: string
  parameters: OperationParameter[]
  body_schema: Record<string, unknown> | null
  body_required: boolean
  output_schema: Record<string, unknown> | null
  usage_note: string
  category: string | null
  risk_level: string | null
  preconditions: string[]
  related_tools: string[]
  read_only: boolean
  destructive: boolean
  idempotent: boolean | null
  pinned: boolean
}

export interface OperationDetailUpdate {
  usage_note?: string
  category?: string | null
  risk_level?: string | null
  preconditions?: string[]
  related_tools?: string[]
  read_only?: boolean | null
  destructive?: boolean | null
  idempotent?: boolean | null
}

export interface ResourceTemplateSummary extends Record<string, unknown> {
  uri_template: string
  name: string
  description: string
}

export interface PromptSummary extends Record<string, unknown> {
  name: string
  description: string | null
}

export interface EventOut extends Record<string, unknown> {
  id: number
  ts: string
  server: string
  kind: string
  name: string
  arguments_json: string
  status: string
  error_message: string | null
  result_summary: string
  duration_ms: number
  pid: number
  action: string | null
  ticket_id: number | null
  comment_count: number
}

export interface CommentOut extends Record<string, unknown> {
  id: number
  event_id: number
  text: string
  created_at: string
}

export interface TicketOut extends Record<string, unknown> {
  id: number
  session_id: string
  title: string
  resource_id: string | null
  state: string
  created_at: string
  closed_at: string | null
  event_count: number
  comment_count: number
  latest_event_name: string | null
  latest_event_status: string | null
  latest_event_ts: string | null
}

export interface ConnectionFields {
  [field: string]: string | undefined
}

export interface TestConnectionResult {
  reachable: boolean
  status_code?: number
  message?: string
}

export interface MaskingPattern extends Record<string, unknown> {
  id: number
  name: string
  regex: string
  enabled: boolean
  built_in: boolean
  sample_retention_count: number
}

export interface MaskMatchSample extends Record<string, unknown> {
  id: number
  matched_at: string
  matched_text: string
  source: string
}

export interface SpecSource extends Record<string, unknown> {
  id: number | null
  server: string
  name: string
  domain: string | null
  spec_path: string
  annotations_path: string | null
  enabled: boolean
  sort_order: number
}

export type FailurePattern = Record<string, unknown> & { id: string }

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, {
    headers: init?.body && !(init.body instanceof FormData) ? { 'Content-Type': 'application/json' } : undefined,
    ...init,
  })
  if (!response.ok) {
    const body = await response.text()
    let detail = body
    try {
      detail = JSON.parse(body).detail ?? body
    } catch {
      // not JSON, use raw body
    }
    throw new Error(`${response.status} ${response.statusText}: ${detail}`)
  }
  if (response.status === 204) return undefined as T
  return response.json() as Promise<T>
}

const json = (body: unknown) => JSON.stringify(body)

export const api = {
  listServers: () => request<ServerSummary[]>('/api/servers'),
  listTools: (serverId: string) => request<ToolSummary[]>(`/api/servers/${serverId}/tools`),
  listAllAdminOperations: () => request<OperationSummary[]>('/api/servers/cmp-admin/tools/all'),
  setPinned: (operationId: string, pinned: boolean) =>
    request<{ pinned: boolean }>(`/api/servers/cmp-admin/tools/${operationId}/pin`, {
      method: 'POST',
      body: json({ pinned }),
    }),
  getOperationDetail: (operationId: string) =>
    request<OperationDetail>(`/api/servers/cmp-admin/tools/${operationId}`),
  updateOperationDetail: (operationId: string, update: OperationDetailUpdate) =>
    request<OperationDetail>(`/api/servers/cmp-admin/tools/${operationId}`, {
      method: 'PUT',
      body: json(update),
    }),
  listResourceTemplates: (serverId: string) =>
    request<ResourceTemplateSummary[]>(`/api/servers/${serverId}/resources`),
  listPrompts: (serverId: string) => request<PromptSummary[]>(`/api/servers/${serverId}/prompts`),

  listEvents: (filters: {
    server?: string
    kind?: string
    status?: string
    ticket_id?: string
    since?: string
    until?: string
    limit?: number
  }) => {
    const params = new URLSearchParams()
    for (const [key, value] of Object.entries(filters)) {
      if (value !== undefined && value !== '') params.set(key, String(value))
    }
    return request<EventOut[]>(`/api/events?${params.toString()}`)
  },
  approveEvent: (eventId: number) => request<{ status: string }>(`/api/events/${eventId}/approve`, { method: 'POST' }),
  denyEvent: (eventId: number) => request<{ status: string }>(`/api/events/${eventId}/deny`, { method: 'POST' }),
  requestEventChanges: (eventId: number, comment: string) =>
    request<{ status: string }>(`/api/events/${eventId}/request-changes`, {
      method: 'POST',
      body: json({ comment }),
    }),
  clearEvents: () => request<{ deleted: number }>('/api/events', { method: 'DELETE' }),
  listComments: (eventId: number) => request<CommentOut[]>(`/api/events/${eventId}/comments`),
  addComment: (eventId: number, text: string) =>
    request<CommentOut>(`/api/events/${eventId}/comments`, { method: 'POST', body: json({ text }) }),

  listTickets: () => request<TicketOut[]>('/api/tickets'),
  getTicket: (id: number) => request<TicketOut>(`/api/tickets/${id}`),
  deleteTicket: (id: number) =>
    request<{ detached_events: number }>(`/api/tickets/${id}`, { method: 'DELETE' }),

  getConnection: (connection: string) => request<ConnectionFields>(`/api/config/${connection}`),
  updateConnection: (connection: string, fields: ConnectionFields) =>
    request<ConnectionFields>(`/api/config/${connection}`, { method: 'PUT', body: json(fields) }),
  testConnection: (connection: string, fields: ConnectionFields) =>
    request<TestConnectionResult>(`/api/config/${connection}/test-connection`, {
      method: 'POST',
      body: json(fields),
    }),

  listMaskingPatterns: () => request<MaskingPattern[]>('/api/masking/patterns'),
  createMaskingPattern: (name: string, regex: string, sampleRetentionCount: number) =>
    request<MaskingPattern>('/api/masking/patterns', {
      method: 'POST',
      body: json({ name, regex, sample_retention_count: sampleRetentionCount }),
    }),
  updateMaskingPattern: (
    id: number,
    update: { regex?: string; enabled?: boolean; sample_retention_count?: number },
  ) => request<MaskingPattern>(`/api/masking/patterns/${id}`, { method: 'PUT', body: json(update) }),
  deleteMaskingPattern: (id: number) =>
    request<void>(`/api/masking/patterns/${id}`, { method: 'DELETE' }),
  listMaskMatchSamples: (patternId: number) =>
    request<MaskMatchSample[]>(`/api/masking/patterns/${patternId}/samples`),
  clearMaskMatchSamples: (patternId: number) =>
    request<void>(`/api/masking/patterns/${patternId}/samples`, { method: 'DELETE' }),

  listSpecSources: (server: string) => request<SpecSource[]>(`/api/spec-sources?server=${server}`),
  addSpecSource: (server: string, name: string, specFile: File, annotationsFile: File | null) => {
    const form = new FormData()
    form.set('server', server)
    form.set('name', name)
    form.set('spec_file', specFile)
    if (annotationsFile) form.set('annotations_file', annotationsFile)
    return request<SpecSource>('/api/spec-sources', { method: 'POST', body: form })
  },
  updateBuiltInSpecSource: (
    server: string,
    domain: string,
    update: { name?: string; enabled?: boolean; specFile?: File | null; annotationsFile?: File | null },
  ) => {
    const form = new FormData()
    form.set('server', server)
    if (update.name !== undefined) form.set('name', update.name)
    if (update.enabled !== undefined) form.set('enabled', String(update.enabled))
    if (update.specFile) form.set('spec_file', update.specFile)
    if (update.annotationsFile) form.set('annotations_file', update.annotationsFile)
    return request<SpecSource>(`/api/spec-sources/built-in/${domain}`, { method: 'PUT', body: form })
  },
  setSpecSourceEnabled: (id: number, enabled: boolean) =>
    request<{ enabled: boolean }>(`/api/spec-sources/${id}`, { method: 'PUT', body: json({ enabled }) }),
  deleteSpecSource: (id: number) => request<void>(`/api/spec-sources/${id}`, { method: 'DELETE' }),

  listFailurePatterns: () => request<FailurePattern[]>('/api/failure-patterns'),
  createFailurePattern: (record: FailurePattern) =>
    request<FailurePattern>('/api/failure-patterns', { method: 'POST', body: json(record) }),
  updateFailurePattern: (patternId: string, record: FailurePattern) =>
    request<FailurePattern>(`/api/failure-patterns/${patternId}`, { method: 'PUT', body: json(record) }),
  deleteFailurePattern: (patternId: string) =>
    request<void>(`/api/failure-patterns/${patternId}`, { method: 'DELETE' }),
}

