const captionTexts = ['notify_admin failed', 'Report approved'];
const results = captionTexts.map(txt => {
  const el = Array.from(document.querySelectorAll('*')).find(e => e.children.length === 0 && e.textContent.trim() === txt);
  if (!el) return {txt, found: false};
  // walk up to the HStack row that has background/padding (the caption strip container)
  let node = el;
  for (let i = 0; i < 5 && node; i++) {
    const bg = getComputedStyle(node).backgroundColor;
    if (bg && bg !== 'rgba(0, 0, 0, 0)') {
      return {txt, bg, tag: node.tagName, depth: i};
    }
    node = node.parentElement;
  }
  return {txt, found: 'no-bg-ancestor'};
});
JSON.stringify(results, null, 2);

