    if (br && br !== '0px' && node.textContent.includes('elastic IP')) {
      cardInfo = {depth:i, borderRadius: br};
    }
    node = node.parentElement;
  }
  const deleteBtn = Array.from(document.querySelectorAll('button[aria-label="Delete ticket"]'))[0];
  const svgPath = deleteBtn ? deleteBtn.querySelector('svg')?.outerHTML.slice(0,150) : null;
  const separators = Array.from(document.querySelectorAll('div')).filter(d => {
    const s = getComputedStyle(d);
    return s.borderBottomWidth === '1px' && d.children.length === 0 && d.textContent === '';
  });
  return JSON.stringify({cardInfo, svgPath, separatorCount: separators.length});
})();

