  const notifyRow = Array.from(document.querySelectorAll('div')).find(d => {
    const s = getComputedStyle(d);
    return s.display === 'flex' && d.textContent.includes('notify_admin') && d.textContent.includes('Escalate to a human admin');
  });
  if (!notifyRow) return 'row not found';
  const rect = notifyRow.getBoundingClientRect();
  const children = Array.from(notifyRow.children).map(c => {
    const r = c.getBoundingClientRect();
    return { tag: c.tagName, cls: c.className.slice(0,30), text: c.textContent.slice(0,30), top: r.top, left: r.left, width: r.width, height: r.height };
  });
  return JSON.stringify({ rowStyle: notifyRow.getAttribute('style'), rowRect: rect, children }, null, 2);
})();

(function(){
