          label="Approve"
          isIconOnly
          size="sm"
          variant="primary"
          icon={<CheckIcon style={{ width: 14, height: 14 }} />}
          onClick={() => onDecide(event.id, true)}
        />
        <Button
          label="Deny"
          isIconOnly
          size="sm"
          variant="destructive"
          icon={<XMarkIcon style={{ width: 14, height: 14 }} />}
          onClick={() => onDecide(event.id, false)}
        />
      </HStack>
    ) : (
      <Text type="body" color="secondary" style={{ flexShrink: 0, fontVariantNumeric: 'tabular-nums', paddingTop: 6 }}>
        {formatDuration(event.duration_ms)}
      </Text>
    )}
  </div>
)

